#!/bin/sh
# Generated by makefile-go. Edit the project installer configuration instead.
set -eu

repo=alswl/mind-forge
binary_name=mf
requested_version=${MF_VERSION:-}
version_variable=MF_VERSION
install_dir=${MF_INSTALL_DIR:-}

asset_suffix() {
    case "$1" in darwin) system=apple-darwin ;; linux) system=unknown-linux-gnu ;; esac
    case "$2" in amd64) cpu=x86_64 ;; arm64) cpu=aarch64 ;; esac
    printf '%s-%s\n' "$cpu" "$system"
}

validate_candidate() {
    installed_version=$("$1" --version) || return 1
    expected=${2#v}
    expected=${expected%%[-+]*}
    reported=$(printf '%s\n' "$installed_version" | awk '$1 == "mf" {version=$2; sub(/[-+].*/, "", version); print version; exit}')
    [ -n "$reported" ] && [ "$reported" = "$expected" ] || return 1
    printf '%s\n' "$installed_version"
}

install_source() {
    repo_root=$1
    shift
    [ "${MF_IMPLEMENTATION:-go}" = go ] || die 'Only the Go implementation is available.'
    [ "$#" -eq 0 ] || die 'Go source installation does not accept arguments.'
    target_dir="${MF_INSTALL_TARGET_DIR:-${XDG_CACHE_HOME:-$HOME/.cache}/mind-forge/go-install-target}"
    case "$target_dir" in /*) ;; *) target_dir="$(pwd)/$target_dir" ;; esac
    log "Building mf from $repo_root"
    make --no-print-directory -C "$repo_root" build MF_BUILD_OUT="$target_dir/mf"
    source_version=$(cat "$repo_root/VERSION")
    install_verified "$target_dir/mf" "$source_version"
}

: "${install_dir:=${XDG_BIN_HOME:-$HOME/.local/bin}}"
base_url="https://github.com/$repo"
download_dir=
staged_install=
log() { printf '==> %s\n' "$*"; }
die() { printf 'Error: %s\n' "$*" >&2; exit 1; }
cleanup() {
    if [ -n "$staged_install" ]; then rm -f "$staged_install"; fi
    if [ -n "$download_dir" ]; then rm -rf "$download_dir"; fi
}
trap cleanup EXIT
trap 'exit 1' HUP INT TERM

install_verified() {
    candidate=$1
    expected_version=$2
    [ ! -d "$install_dir/$binary_name" ] || die "Install destination is a directory: $install_dir/$binary_name"
    mkdir -p "$install_dir" || die "Cannot create install directory: $install_dir"
    staged_install=$(mktemp "$install_dir/.$binary_name-install.XXXXXX") || die "Cannot stage installation in $install_dir"
    install -m 0755 "$candidate" "$staged_install" || die 'Cannot stage the candidate'
    if command -v validate_candidate >/dev/null 2>&1; then
        candidate_report=$(validate_candidate "$staged_install" "$expected_version") || die "Candidate validation failed; existing $binary_name was preserved"
    fi
    mv -f "$staged_install" "$install_dir/$binary_name" || die "Cannot replace $install_dir/$binary_name"
    staged_install=
    log "Installed $binary_name -> $install_dir/$binary_name"
    if [ -n "${candidate_report:-}" ]; then printf '%s\n' "$candidate_report"; fi
    case ":$PATH:" in
        *":$install_dir:"*) ;;
        *) log "$install_dir is not on PATH; add it with: export PATH=\"$install_dir:\$PATH\"" ;;
    esac
}

if command -v install_source >/dev/null 2>&1; then
    case "$0" in
        */install.sh|install.sh)
            script_root=$(CDPATH='' cd -- "$(dirname -- "$0")/.." 2>/dev/null && pwd || true)
            if [ -n "$script_root" ] && [ -f "$script_root/go.mod" ]; then
                install_source "$script_root" "$@"
                exit 0
            fi
            ;;
    esac
fi
[ "$#" -eq 0 ] || die 'Remote installation does not accept arguments.'

tag=${requested_version:-}
if [ -z "$tag" ]; then
    redirect=$(curl -fsSL -o /dev/null -w '%{url_effective}' "$base_url/releases/latest" 2>/dev/null) || redirect=
    case "$redirect" in "$base_url"/releases/tag/*) tag=${redirect##*/} ;; esac
fi
if [ -z "$tag" ]; then
    response=$(curl -fsSL "https://api.github.com/repos/$repo/releases/latest" 2>/dev/null) || response=
    tag=$(printf '%s\n' "$response" | awk '{json=json $0 "\n"} END {if (match(json, /"tag_name"[[:space:]]*:[[:space:]]*"[^"]+"/)) {value=substr(json,RSTART,RLENGTH); sub(/^[^:]*:[[:space:]]*"/,"",value); sub(/"$/,"",value); print value}}')
fi
case "$tag" in *[!a-zA-Z0-9.+-]*) die 'Invalid release tag' ;; esac
printf '%s\n' "$tag" | grep -Eq '^v[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$' ||
    die "Could not determine a valid release version. Set ${version_variable:-VERSION} explicitly."

case "$(uname -s)" in Darwin) os=darwin ;; Linux) os=linux ;; *) die 'Unsupported operating system' ;; esac
case "$(uname -m)" in x86_64|amd64) arch=amd64 ;; aarch64|arm64) arch=arm64 ;; *) die 'Unsupported architecture' ;; esac
if command -v asset_suffix >/dev/null 2>&1; then
    target=$(asset_suffix "$os" "$arch")
else
    target="$os-$arch"
fi
case "$target" in ''|*[!a-zA-Z0-9._-]*) die 'Invalid asset suffix' ;; esac

download_dir=$(mktemp -d)
asset="$binary_name-$tag-$target.tar.gz"
member="$binary_name-$target"
url="$base_url/releases/download/$tag"
log "Downloading $asset"
curl -fsSL --retry 3 --retry-delay 2 "$url/$asset" -o "$download_dir/$asset" || die "Failed to download $asset"
curl -fsSL "$url/checksums.txt" -o "$download_dir/checksums.txt" || die "Could not download checksums for $tag"
expected=$(awk -v a="$asset" '$2 == a {hash=$1; count++} END {if (count == 1) print hash; else exit 1}' "$download_dir/checksums.txt") ||
    die "Expected one checksum entry for $asset"
if command -v sha256sum >/dev/null 2>&1; then
    actual=$(sha256sum < "$download_dir/$asset")
elif command -v shasum >/dev/null 2>&1; then
    actual=$(shasum -a 256 < "$download_dir/$asset")
else
    die 'Install sha256sum or shasum to verify the downloaded release'
fi
[ "${actual%% *}" = "$expected" ] || die "Checksum mismatch for $asset"

members=$(LC_ALL=C tar -tvzf "$download_dir/$asset" "$member") || die "Failed to inspect $asset"
printf '%s\n' "$members" | awk 'NR != 1 || substr($0, 1, 1) != "-" {bad=1} END {exit bad || NR != 1}' ||
    die 'Archive member is not a unique regular file'
# Stream only the named member into a file we control.
tar -xOzf "$download_dir/$asset" "$member" > "$download_dir/candidate" || die "Failed to extract $asset"
[ -s "$download_dir/candidate" ] || die 'Archive member is empty'
install_verified "$download_dir/candidate" "$tag"
